import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Baq27OmJ.js";var i=JSON.parse(`{"title":"Read the Docs as Markdown","description":"","frontmatter":{},"headers":[],"relativePath":"skills/docs/read-the-docs-as-markdown.md","filePath":"skills/docs/read-the-docs-as-markdown.md"}`),a={name:`skills/docs/read-the-docs-as-markdown.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="read-the-docs-as-markdown" tabindex="-1">Read the Docs as Markdown <a class="header-anchor" href="#read-the-docs-as-markdown" aria-label="Permalink to “Read the Docs as Markdown”">​</a></h1><p>Use this skill whenever you need something from WarpDrive&#39;s guides, upgrade notes, or API reference that no other skill covers: a concept, a config option, a signature, a deprecation. The published site at <code>https://warp-drive.io</code> serves every page as plain Markdown, so you never have to read or scrape its HTML.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Fetch <code>https://warp-drive.io/llms.txt</code>. It is the table of contents: one absolute link per page, grouped by section, with the page title as the link text and, where the page provides one, a one-line description after a colon. Pick the one or two pages that match your task and fetch only those.</li><li>Fetch the page. Every link in <code>llms.txt</code> already ends in <code>.md</code> and returns raw Markdown. To reach a page from any other URL you were given, append <code>.md</code>: <code>https://warp-drive.io/guides/the-manual/requests/builders</code> becomes <code>https://warp-drive.io/guides/the-manual/requests/builders.md</code>. If the URL ends in <code>/</code>, drop the slash first (<code>/guides/installation/</code> becomes <code>/guides/installation.md</code>) or append <code>index.md</code>; both exist.</li><li>Resolve links inside a page against <code>https://warp-drive.io</code>. Cross-references in the Markdown are root-relative and already end in <code>.md</code>, such as <code>/guides/the-manual/schemas/resources/legacy-mode.md</code>, so following one is the same fetch with no guessing. The <code>url:</code> line in each page&#39;s opening <code>---</code> block is the canonical URL to cite.</li><li>Read the site&#39;s Markdown extensions as what they render to: <ul><li><code>:::tip</code>, <code>:::info</code>, <code>:::warning</code>, or <code>:::danger</code> through the closing <code>:::</code> is a callout box. Text on the opening line is the box&#39;s title.</li><li><code>:::tabs</code> through <code>:::</code> holds alternatives. Each <code>== Label</code> line starts one tab. When the labels are frameworks or package managers, read only the tab that matches the app you are working in.</li><li><code>::: code-group</code> through <code>:::</code> is the same for code: the <code>[Label]</code> after each fence&#39;s language names its tab.</li><li>Comments like <code>// [!code focus]</code> or <code>// [!code ++]</code> inside a fence are highlighting hints for the website. Ignore them; they are not part of the code.</li></ul></li><li>Reach for <code>https://warp-drive.io/llms-full.txt</code> only when you need the whole corpus at once. It concatenates every page, is a few megabytes, and each page in it opens with the same <code>---</code> / <code>url:</code> block, so you can still tell which page a passage came from. <code>llms.txt</code> plus one page is almost always enough.</li></ol><p>Both <code>warp-drive.io</code> and <code>https://canary.warp-drive.io</code> are built from the repository&#39;s <code>main</code> branch; canary is redeployed on every merge and production on demand, so canary may be newer.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};